import 'dart:convert';
import 'dart:io';

import 'package:crypto/crypto.dart';
import 'package:flutter_test/flutter_test.dart';

// The bundled question bank is generated by tool/content/extract_questions.py
// and never edited by hand: these checks catch a manual edit or a stale
// manifest before the importer (next milestone) ever sees it.
void main() {
  const dir = 'assets/content/armas/GC-2020-11';
  final questionsBytes = File('$dir/questions.json').readAsBytesSync();
  final manifest = jsonDecode(
    File('$dir/manifest.json').readAsStringSync(),
  ) as Map<String, dynamic>;
  final questions = (jsonDecode(utf8.decode(questionsBytes)) as List)
      .cast<Map<String, dynamic>>();

  test('questions.json matches the manifest checksum', () {
    expect(
      sha256.convert(questionsBytes).toString(),
      manifest['questions_sha256'],
    );
  });

  test('counts match the manifest (423 in 7 temas)', () {
    expect(questions, hasLength(423));
    expect(manifest['question_count'], 423);
    final perTema = <String, int>{};
    for (final q in questions) {
      perTema.update('${q['tema']}', (n) => n + 1, ifAbsent: () => 1);
    }
    expect(perTema, Map<String, dynamic>.from(manifest['per_tema'] as Map));
  });

  test('our own layer is well formed (explanation, article, notice)', () {
    for (final q in questions) {
      final id = '${q['id']}';
      // Every entry carries the notice key, null or {"es": text}.
      expect(q.containsKey('notice'), isTrue, reason: id);
      final notice = q['notice'];
      final explanation = q['explanation'];
      for (final field in [explanation, notice]) {
        if (field != null) {
          expect(field, isA<Map>(), reason: id);
          expect(((field as Map)['es'] as String).trim(), isNotEmpty);
        }
      }
      // A notice always comes with its discrepancy flag, and vice versa.
      final flags = (q['flags'] as List).cast<String>();
      final discrepancy = flags.any((f) => f.startsWith('discrepancia_'));
      expect(notice != null, discrepancy, reason: id);
      // Internal review fields are never shipped.
      for (final internal in ['confidence', 'sources', 'review_notes']) {
        expect(q.containsKey(internal), isFalse, reason: '$id $internal');
      }
    }
  });

  test('ids are unique and every question is a valid mc3', () {
    final ids = questions.map((q) => q['id']).toSet();
    expect(ids, hasLength(questions.length));
    for (final q in questions) {
      final options = q['options'] as List;
      expect(q['type'], 'mc3', reason: '${q['id']}');
      expect(options, hasLength(3), reason: '${q['id']}');
      expect(
        options.every((o) => (o as String).trim().isNotEmpty),
        isTrue,
        reason: '${q['id']}',
      );
      expect(q['answer'], inInclusiveRange(0, 2), reason: '${q['id']}');
      expect(q['edition'], 'GC-2020-11', reason: '${q['id']}');
    }
  });
}
